insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 165, 'ആദ്യമായി വസ്ത്രം ധരിപ്പിക്കപ്പെടുന്നവൻ', null, 897 from books where volume_id=1 and book_no=31 on conflict (book_id, chapter_no) do nothing;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ جَابِر بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: غَزَوْنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَوْمًا مِنْ جُهَيْنَةَ، فَقَاتَلُونَا قِتَالًا شَدِيدًا، فَلَمَّا صَلَّيْنَا الظُّهْرَ قَالَ الْمُشْرِكُونَ: لَوْ مِلْنَا عَلَيْهِمْ مَيْلَةً لَاقْتَطَعْنَاهُمْ. فَأَخْبَرَ جِبْرِيلُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذلك، فَذَكَرَ ذَلِكَ لَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ: "وَقَالُوا: إِنَّهُ سَتَأْتِيهِمْ صَلَاةٌ، هِيَ أَحَبُّ إِلَيْهِمْ مِنَ الْأَوْلَادِ". فَلَمَّا حَضَرَتِ الْعَصْرُ، قَالَ :صَفْنَا صَفَّيْنِ، وَالْمُشْرِكُونَ بَيْنَنَا وَبَيْنَ الْقِبْلَةِ. قَالَ: فَكَبَّرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَكَبَّرْنَا، وَرَكَعَ فَرَكَعْنَا، ثُمَّ سَجَدَ وَسَجَدَ مَعَهُ الصَّفُّ الْأَوَّلُ، فَلَمَّا قَامُوا سَجَدَ الصَّفُّ الثَّانِي، ثُمَّ تَأَخَّرَ الصَّفُّ الْأَوَّلُ، وَتَقَدَّمَ الصَّفُّ الثَّانِي، فَقَامُوا مَقَامَ الْأَوَّلِ، فَكَبَّرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَكَبَّرْنَا، وَرَكَعَ فَرَكَعْنَا، ثُمَّ سَجَدَ مَعَهُ الصَّفُّ الْأَوَّلُ وَقَامَ الثَّانِي، فَلَمَّا سَجَدَ الصَّفُّ الثَّانِي ثُمَّ جَلَسُوا جَمِيعًا، سَلَّمَ عَلَيْهِمْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. قَالَ أَبُو الزُّبَيْرِ: ثُمَّ خَصَّ جَابِرٌ أَنْ قَالَ: كَمَا يُصَلِّي أُمَرَاؤُكُمْ هَؤُلَاءِ. (م)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): ജുഹൈന ഗോത്രത്തിലെ ഒരുവിഭാഗം ആളുകളുമായി നബി(സ)യോടൊപ്പം ഞങ്ങൾ യുദ്ധം ചെയ്തു. അവർ ഞങ്ങളുമായി കഠിന യുദ്ധമാണ് ചെയ്തത്. ഞങ്ങൾ ളുഹ്ർ നിസ്കരിച്ചപ്പോൾ ബഹുദൈവവിശ്വാസികൾ പറഞ്ഞു: (അവർ നിസ്കരിക്കുമ്പോൾ) നാം മിന്നലാക്രമണം നടത്തിയാൽ അവരെ ഉന്മൂലനം ചെയ്യാൻ സാധിക്കും. ഈ വിവരം ജിബ്രീൽ(അ) നബി(സ)യെ അറിയിക്കുകയും നബി(സ) അത് ഞങ്ങളോട് പറയുകയും ചെയ്തു. നബി(സ) പറഞ്ഞു: "മുശ്രികുകൾ പരസ്പരം പറഞ്ഞു: അവർക്കൊരു നിസ്കാരം നിർവ്വഹിക്കാനുണ്ട്. അതവർക്ക് അവരുടെ സന്താനങ്ങളേക്കാൾ പ്രിയപ്പെട്ടതാണ്." അസ്വർ നിസ്കാര സമയമായപ്പോൾ നബി(സ) ഞങ്ങളെ രണ്ട് അണികളാക്കി നിർത്തി. ഖിബ്ലയുടെയും ഞങ്ങളുടെയും മദ്ധ്യേയായിരുന്നു മുശ്രികുകൾ. ജാബിർ(റ) പറയുന്നു: നബി(സ) തക്ബീർ ചൊല്ലി, ഞങ്ങളും തക്ബീർ ചൊല്ലി. നബി(സ)യും ഞങ്ങളും റുകൂഅ് ചെയ്തു. പിന്നെ നബി(സ) സുജൂദ് ചെയ്തു, നബി(സ)യോടൊപ്പം ഒന്നാമത്തെ അണി(സംഘം)യും സുജൂദ് ചെയ്തു. അവർ എഴുന്നേറ്റു നിന്നപ്പോൾ രണ്ടാമത്തെ അണിയും സുജൂദ് ചെയ്തു. പിന്നെ ഒന്നാമത്തെ അണി പിന്നോട്ടു മാറി. രണ്ടാമത്തെ അണി മുന്നോട്ട് ചെന്ന് ഒന്നാമത്തെ അണിയുടെ സ്ഥാനത്ത് നിലയുറപ്പിച്ചു. നബി(സ) തക്ബീർ ചൊല്ലി, ഞങ്ങളും തക്ബീർ ചൊല്ലി, നബി(സ) റുകൂഅ് ചെയ്തപ്പോൾ ഞങ്ങളും റുകൂഅ് ചെയ്തു. പിന്നീട് നബി(സ) സുജൂദ് ചെയ്തു, നബി(സ)യോടൊപ്പം ഒന്നാമത്തെ അണിയും സുജൂദ് ചെയ്തു. രണ്ടാമത്തെ അണി നിൽക്കുകയും ചെയ്തു. രണ്ടാമത്തെ അണി സുജൂദ് ചെയ്തു കഴിഞ്ഞ് എല്ലാവരും ഇരുന്നു. തുടർന്ന് നബി(സ) സലാം വീട്ടി. അബൂസുബൈർ പറഞ്ഞു: പിന്നീട് ജാബിർ(റ) ''നിങ്ങളുടെ ഈ നേതാക്കൾ നിസ്കരിക്കുന്നത് പോലെ'' എന്ന് പ്രത്യേകം പറയുകയുണ്ടായി.¹ (മു)', 'جَابِر بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', '¹. ഖൗഫ് എന്നാൽ ഭയം, പേടി എന്നാണർത്ഥം. ഇവിടെ ''സ്വലാത്തുൽ ഖൗഫ്'' എന്നതുകൊണ്ടുള്ള ഉദ്ദേശ്യം യുദ്ധ വേളയിലെ നിസ്കാരം എന്നാണ്.', null, array['م']::text[], array['മു']::text[], null, null, 683, 683, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=0 where b.volume_id=1 and b.book_no=27 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي صَلَاةِ الْخَوْفِ: "أَنْ يَكُونَ الْإِمَامُ يُصَلِّي بِطَائِفَةٍ مَعَهُ، فَيَسْجُدُونَ سَجْدَةً وَاحِدَةً، وَتَكُونُ طَائِفَةٌ مِنْهُمْ بَيْنَهُمْ وَبَيْنَ الْعَدُوِّ، ثُمَّ يَنْصَرِفُ الَّذِينَ سَجَدُوا السَّجْدَةَ مَعَ أَمِيرِهِمْ، ثُمَّ يَكُونُونَ مَكَانَ الَّذِينَ لَمْ يُصَلُّوا. وَيَتَقَدَّمُ الَّذِينَ لَمْ يُصَلُّوا فَيُصَلُّوا مَعَ أَمِيرِهِمْ سَجْدَةً وَاحِدَةً، ثُمَّ يَنْصَرِفُ أَمِيرُهُمْ وَقَدْ صَلَّى صَلَاتَهُ، وَيُصَلِّي كُلُّ وَاحِدٍ مِنَ الطَّائِفَتَيْنِ بِصَلَاتِهِ سَجْدَةً لِنَفْسِهِ، فَإِنْ كَانَ خَوْفٌ أَشَدَّ مِنْ ذَلِكَ فَرِجَالًا أَوْ رُكْبَانًا". (خ,ن,جه)', 'ഇബ്നുഉമർ(റ): സ്വലാത്തുൽ ഖൗഫിനെപ്പറ്റി നബി(സ) പറഞ്ഞു: "ഇമാം ഒരു വിഭാഗം ആളുകളുമായി നിസ്കരിക്കണം. അവർ ഒരു റക്അത്ത് നിസ്കരിക്കണം, മറ്റൊരു വിഭാഗം ആദ്യ വിഭാഗത്തിന്റെയും ശത്രുവിന്റെയും ഇടയിലായിരിക്കണം. ഇമാമിനോടൊപ്പം ഒരു റക്അത്ത് നിസ്കരിച്ചവർ മാറിയ ശേഷം നിസ്കരിക്കാത്തവരുടെ സ്ഥാനത്ത് വരികയും, നിസ്കരിക്കാത്തവർ മുന്നോട്ടു ചെന്ന് അവരുടെ ഇമാമിനൊപ്പം ഒരു റക്അത്ത് നിസ്കരിക്കുകയും വേണം. പിന്നീട് നിസ്കാരം പൂർത്തിയാക്കി ഇമാം വിരമിക്കുന്നു, ബാക്കി ഒരോ റക്അത്ത് രണ്ട് വിഭാഗത്തിലെയും ആളുകൾ സ്വന്തമായി നിസ്കരിക്കേണ്ടതുമാണ്. കഠിന ഭയമുള്ള സന്ദർഭമാണെങ്കിൽ നിസ്കാരം നടന്നോ, വാഹനപ്പുറത്തോ ആയി നിർവ്വഹിക്കാവുന്നതാണ്." (ബു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','ن','جه']::text[], array['ബു','ന','ജ']::text[], null, null, 683, 684, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=0 where b.volume_id=1 and b.book_no=27 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ سَهْلِ بْنِ أَبِي حَثْمَةَ رَضِيَ اللهُ عَنْهُ، فِي صَلَاةِ الْخَوْفِ: يَقُومُ الْإِمَامُ مُسْتَقْبِلَ الْقِبْلَةِ، وَتَقُومُ طَائِفَةٌ مِنْهُمْ مَعَهُ، وَطَائِفَةٌ قِبَلَ الْعَدُوِّ، وَوُجُوهُهُمْ إِلَى الْعَدُوِّ، فَيَرْكَعُ بِهِمْ رَكْعَةً، وَيَرْكَعُونَ لِأَنْفُسِهِمْ وَيَسْجُدُونَ سَجْدَتَيْنِ فِي مَكَانِهِمْ، وَيَذْهَبُونَ إِلَى مَقَامِ أُولَئِكَ، وَيَجِيءُ أُولَئِكَ فَيَرْكَعُ بِهِمْ وَيَسْجُدُ بِهِمْ سَجْدَتَيْنِ، فَهِيَ لَهُ ثِنْتَانِ وَلَهُمْ وَاحِدَةٌ، ثُمَّ يَرْكَعُونَ رَكْعَةً وَيَسْجُدُونَ سَجْدَتَيْنِ. (ق,د,ت,ن,جه)', 'സഹ്ലുബ്നു അബീഹസ്മ(റ) സ്വലാത്തുൽ ഖൗഫിനെപ്പറ്റി പറഞ്ഞു: ഇമാം ഖിബ്ലക്കഭിമുഖമായി നിൽക്കണം. ഒരു വിഭാഗമാളുകൾ അദ്ദേഹത്തോടൊപ്പവും, മറ്റേ വിഭാഗം ശത്രുക്കളുടെ നേരെയും നിലയുറപ്പിക്കണം. അവരുടെ മുഖം ശത്രുക്കളുടെ നേരെയായിരിക്കണം. ഇമാം അവരോടൊപ്പം ഒരു റക്അത്ത് നിസ്കരിക്കണം. തുടർന്ന് അവർ അവരുടെ സ്ഥാനത്ത് നിന്ന് സ്വന്തമായി ഒരു റകൂഉം രണ്ട് സുജൂദും ചെയ്യുകയും ഒരു റക്അത്ത് പൂർത്തിയാക്കി മറ്റേ വിഭാഗത്തിന്റെ അടുത്തേക്ക് മടങ്ങിപ്പോവുകയും വേണം. അവർ വന്ന് ഇമാമിനോടൊപ്പം ഒരു റക്അത്ത് നിസ്കരിക്കണം. അപ്പോൾ ഇമാമിന് രണ്ട് റക്അത്തും, രണ്ടാമത്തെ വിഭാഗത്തിന് ഒരു റക്അത്തും ലഭിക്കുന്നു. പിന്നീടവർ ഒരു റുകൂഉം രണ്ട് സുജൂദും (ഒരു റക്അത്ത്) ചെയ്യേണ്ടതാണ്. (ബു,മു,ദ,തു,ന,ജ)', 'سَهْلِ بْنِ أَبِي حَثْمَةَ', 'സഹ്ലുബ്നു അബീഹസ്മ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 684, 684, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=0 where b.volume_id=1 and b.book_no=27 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ أَبِي عَيَّاشٍ الزُّرَقِيِّ رَضِيَ اللهُ عَنْهُ :أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ مُصَافَّ الْعَدُوِّ بِعُسْفَانَ، وَعَلَى الْمُشْرِكِينَ خَالِدُ بْنُ الْوَلِيدِ، فَصَلَّى بِهِمُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الظُّهْرَ، قَالَ الْمُشْرِكُونَ: إِنَّ لَهُمْ صَلَاةً بَعْدَ هذه، هِيَ أَحَبُّ إِلَيْهِمْ مِنْ أَمْوَالِهِمْ وَأَبْنَائِهِمْ، فَصَلَّى بِهِمْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْعَصْرَ، فَصَفَّهُمْ صَفَّيْنِ خَلْفَهُ، فَرَكَعَ بِهِمْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جَمِيعًا، فَلَمَّا رَفَعُوا رُءُوسَهُمْ سَجَدَ بِالصَّفِّ الَّذِي يَلِيهِ وَقَامَ الْآخَرُونَ، فَلَمَّا رَفَعُوا رُءُوسَهُمْ مِنَ السُّجُودِ سَجَدَ الصَّفُّ الْمُؤَخَّرُ بِرُكُوعِهِمْ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ تَأَخَّرَ الصَّفُّ الْمُقَدَّمُ، وَتَقَدَّمَ الصَّفُّ الْمُؤَخَّرُ، فَقَامَ كُلُّ وَاحِدٍ مِنْهُمْ فِي مَقَامِ صَاحِبِهِ، ثُمَّ رَكَعَ بِهِمْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جَمِيعًا، فَلَمَّا رَفَعُوا رُءُوسَهُمْ مِنَ الرُّكُوعِ سَجَدَ الصَّفُّ الَّذِي يَلِيهِ وَقَامَ الْآخَرُونَ، فَلَمَّا فَرَغُوا مِنْ سُجُودِهِمْ سَجَدَ الْآخَرُونَ، ثُمَّ سَلَّمَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَيْهِمْ. (ن)', 'അബീ അയ്യാഷുസ്സുറഖി(റ): ഉസ്ഫാൻ എന്ന സ്ഥലത്ത് നബി(സ) (വിശ്വാസികളെ അണിനിർത്തികൊണ്ട്) ശത്രുക്കളെ അഭിമുഖീകരിച്ച് നിന്നു. ബഹുദൈവ വിശ്വാസികളെ നയിച്ചിരുന്നത് ഖാലിദുബ്നുൽ വലീദ് ആയിരുന്നു. (അവിടെ വെച്ച്) നബി(സ) ഞങ്ങൾക്ക് ഇമാമായി ളുഹ്ർ നിസ്കരിച്ചു. ബഹുദൈവ വിശ്വാസികൾ പറഞ്ഞു: ഇവർക്ക് ഇതിനുശേഷം ഒരു നിസ്കാരമുണ്ട്, തങ്ങളുടെ സന്താനത്തെക്കാളും, സമ്പത്തിനെക്കാളും അതവർക്ക് പ്രിയപ്പെട്ടതാണ്. അങ്ങനെ നബി(സ) അവരോടൊപ്പം അസ്വർ നിസ്കരിച്ചു. നബി(സ)ക്കു പിന്നിൽ അവരെ ഈരണ്ട് അണികളാക്കി നിർത്തി. എല്ലാവരോടുമൊപ്പം റുകൂഅ് ചെയ്തു, റുകൂഇൽ നിന്ന് തലയുയർത്തിയപ്പോൾ നബി(സ) അടുത്തുള്ള അണിയോടൊപ്പം സുജൂദ് ചെയ്തു. അപ്പോൾ മറ്റേ അണി നിൽക്കുകയായിരുന്നു. അവർ സുജൂദിൽ നിന്നുയർന്നപ്പോൾ നബി(സ)യോടൊപ്പം റുകൂഅ് ചെയ്ത രണ്ടാമത്തെ അണിയിലുള്ളവർ സുജൂദ് ചെയ്തു. തുടർന്ന് ആദ്യത്തെ അണി പിന്നോട്ടു മാറി, രണ്ടാമത്തെ അണി മുന്നോട്ടു വന്ന് ഓരോരുത്തരും തന്റെ കൂട്ടുകാരന്റെ സ്ഥാനത്ത് നിന്നു. പിന്നെ നബി(സ) എല്ലാവരോടുമൊപ്പം റുകൂഅ് ചെയ്തു. അവരെല്ലാം റുകൂഇൽ നിന്ന് തലയുയർത്തിയപ്പോൾ നബി(സ)ക്ക് അടുത്തുള്ള അണിയിലുള്ളവർ സുജൂദ് ചെയ്തു. മറ്റേ അണി നിൽക്കുകയായിരുന്നു. അവർ സുജൂദിൽ നിന്ന് വിരമിച്ചപ്പോൾ മറ്റുള്ളവർ സുജൂദ് ചെയ്യുകയും, പിന്നീട് നബി(സ) സലാം വീട്ടുകയും ചെയ്തു. (ന)', 'أَبِي عَيَّاشٍ الزُّرَقِيِّ', 'അബീ അയ്യാഷുസ്സുറഖി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 684, 685, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=0 where b.volume_id=1 and b.book_no=27 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ أَبِي عَيَّاشٍ الزُّرَقِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِعُسْفَانَ، فَصَلَّى بِنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الظُّهْرِ، وَعَلَى الْمُشْرِكِينَ يَوْمَئِذٍ خَالِدُ بْنُ الْوَلِيدِ، فَقَالَ الْمُشْرِكُونَ: لَقَدْ أَصَبْنَا مِنْهُمْ غِرَّةً، وَلَقَدْ أَصَبْنَا مِنْهُمْ غَفْلَةً. فَنَزَلَتْ - يَعْنِي صَلَاةَ الْخَوْفِ - بَيْنَ الظُّهْرِ وَالْعَصْرِ، فَصَلَّى بِنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الْعَصْرِ، فَفَرَّقَنَا فِرْقَتَيْنِ، فِرْقَةً تُصَلِّي مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَفِرْقَةً يَحْرُسُونَهُ، فَكَبَّرَ بِالَّذِينَ يَلُونَهُ وَالَّذِينَ يَحْرُسُونَهُمْ، ثُمَّ رَكَعَ فَرَكَعَ هَؤُلَاءِ وَأُولَئِكَ جَمِيعًا، ثُمَّ سَجَدَ الَّذِينَ يَلُونَهُ وَتَأَخَّرَ هَؤُلَاءِ وَالَّذِينَ يَلُونَهُ، وَتَقَدَّمَ الْآخَرُونَ فَسَجَدُوا، ثُمَّ قَامَ فَرَكَعَ بِهِمْ جَمِيعًا الثَّانِيَةَ بِالَّذِينَ يَلُونَهُ وَبِالَّذِينَ يَحْرُسُونَهُ، ثُمَّ سَجَدَ بِالَّذِينَ يَلُونَهُ ثُمَّ تَأَخَّرُوا، فَقَامُوا فِي مُصَافِّ أَصْحَابِهِمْ، وَتَقَدَّمَ الْآخَرُونَ فَسَجَدُوا، ثُمَّ سَلَّمَ عَلَيْهِمْ، فَكَانَتْ لِكُلِّهِمْ رَكْعَتَانِ مَعَ إِمَامِهِمْ، وَصَلَّى مَرَّةً بِأَرْضِ بَنِي سُلَيْمٍ. (د,ن)', 'അബീഅയ്യാശുസ്സുറഖി(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പം ഉസ്ഫാൻ എന്ന സ്ഥലത്തായിരുന്നു. നബി(സ) ഞങ്ങളോടൊപ്പം ളുഹ്ർ നിസ്കരിച്ചു. അന്ന് ബഹുദൈവ വിശ്വാസികളെ നയിച്ചിരുന്നത് ഖാലിദുബ്നുൽ വലീദ് ആയിരുന്നു. (അവരെ പരാജയപ്പെടുത്താൻ) പറ്റിയ ഒരവസരം നമുക്ക് ലഭിച്ചിരിക്കുന്നു, അവരിൽ നിന്ന് അശ്രദ്ധമായ ഒരവസരം നമുക്ക് ലഭിച്ചിരിക്കുന്നു എന്ന് മുശ്രികുകൾ പറയുന്നുണ്ടായിരുന്നു. തദവസരം, അസ്റിന്റെയും ളുഹ്റിന്റെയും മദ്ധ്യേ സ്വലാതുൽ ഖൗഫിനെപ്പറ്റിയുള്ള വചനം അവതരിച്ചു. അങ്ങനെ നബി(സ) ഞങ്ങളോടൊപ്പം അസർ നിസ്കരിച്ചു. നബി(സ) ഞങ്ങളെ രണ്ട് ഭാഗമാക്കി. ഒരു വിഭാഗം നബിയോടൊപ്പം നിസ്കരിച്ചു. ഒരു വിഭാഗം നബി(സ)യെ സംരക്ഷിച്ചു കൊണ്ട് നിന്നു. നബി(സ) തിരുമേനിയോടടുത്തുള്ളവരോടൊപ്പവും, സംരക്ഷിക്കുന്നവരോടൊപ്പവും അവിടുന്നു തക്ബീർ ചൊല്ലി. പിന്നെ അവരെല്ലാം റുകൂഅ് ചെയ്തു. പിന്നെ അടുത്തുള്ളവരോടൊപ്പം സുജൂദ് ചെയ്തു. പിന്നെ അവരും നബി(സ)യുടെ അടുത്തുള്ളവരും പിന്നോട്ടു മാറി, മറ്റുള്ളവർ മുന്നോട്ടു വന്ന് സുജൂദ് ചെയ്തു. ശേഷം നബി(സ) എഴുന്നേറ്റ്നിന്ന് സംരക്ഷകരായി നിന്നവർ അടക്കമുള്ള എല്ലാവരോടുമൊപ്പം രണ്ടാമത്തെ റുകൂഅ് ചെയ്തു. പിന്നെ നബി(സ) അടുത്തുള്ളവരോടൊപ്പം സുജൂദ് ചെയ്തു. തുടർന്ന് അവർ പിൻവാങ്ങി. അവരുടെ കൂട്ടുകാർ നിന്ന സ്ഥലത്തെത്തി. മറ്റേ അണി മുന്നോട്ടു വരികയും, സുജൂദ് ചെയ്യുകയും ചെയ്തു. തുടർന്ന് നബി(സ) സലാം ചൊല്ലി. അങ്ങനെ ഓരോ വിഭാഗത്തിനും ഇമാമിനോടൊപ്പം രണ്ടു റക്അത്തുകൾ വീതം കിട്ടി. മറ്റൊരിക്കൽ നബി(സ) ബനൂസുലൈമിന്റെ നാട്ടിലും സ്വലാത്തുൽ ഖൗഫ് നിർവ്വഹിച്ചിട്ടുണ്ട്. (ദ,ന)', 'أَبِي عَيَّاشٍ الزُّرَقِيِّ', 'അബീഅയ്യാശുസ്സുറഖി(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 685, 685, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=0 where b.volume_id=1 and b.book_no=27 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ سَهْلِ بْنِ أَبِي حَثْمَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى بِأَصْحَابِهِ فِي خَوْفٍ، فَجَعَلَهُمْ خَلْفَهُ صَفَّيْنِ، فَصَلَّى بِالَّذِينَ يَلُونَهُ رَكْعَةً، ثُمَّ قَامَ، فَلَمْ يَزَلْ قَائِمًا حَتَّى صَلَّى الَّذِينَ خَلْفَهُمْ رَكْعَةً، ثُمَّ تَقَدَّمُوا وَتَأَخَّرَ الَّذِينَ كَانُوا قُدَّامَهُمْ، فَصَلَّى بِهِمُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَكْعَةً، ثُمَّ قَعَدَ حَتَّى صَلَّى الَّذِينَ تَخَلَّفُوا رَكْعَةً، ثُمَّ سَلَّمَ. (ق,د,ت,ن,جه)', 'സഹ്ലുബ്നു അബീഹസ്മ(റ): നബി(സ) സ്വഹാബികളോടൊപ്പം ഭയമുള്ളപ്പോൾ നിസ്കരിച്ചിട്ടുണ്ട്. അവരെ രണ്ട് അണികളാക്കി തിരിച്ചു. നബി(സ)യുടെ അടുത്തുള്ളവരുമായി ഓരോ റക്അത്ത് നിർവ്വഹിച്ചു. ശേഷം പിന്നിലുള്ളവർ (രണ്ടാമത്തെ അണി) നിസ്കരിക്കുന്നതു വരെ എഴുന്നേറ്റു നിന്നു. പിന്നീടവർ മുന്നോട്ടു വന്നു, മുമ്പിലുള്ളവർ പിന്നോട്ടും (വന്നു). നബി(സ) അവരുമായി ഒരു റക്അത്ത് നിർവ്വഹിച്ചു. തുടർന്ന് പിന്നിലുള്ളവർ ഒരു റക്അത്ത് നിസ്കരിക്കുന്നതുവരെ നബി(സ) ഇരുന്നു, പിന്നെ സലാം വീട്ടി. (ബു,മു,ദ,തു,ന,ജ)', 'سَهْلِ بْنِ أَبِي حَثْمَةَ', 'സഹ്ലുബ്നു അബീഹസ്മ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 685, 686, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=0 where b.volume_id=1 and b.book_no=27 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَازِلًا بَيْنَ ضَجْنَانَ وَعُسْفَانَ مُحَاصِرَ الْمُشْرِكِينَ، فَقَالَ الْمُشْرِكُونَ: إِنَّ لِهَؤُلَاءِ صَلَاةً هِيَ أَحَبُّ إِلَيْهِمْ مِنْ أَبْنَائِهِمْ وَأَبْكَارِهِمْ، أَجْمِعُوا أَمْرَكُمْ ثُمَّ مِيلُوا عَلَيْهِمْ مَيْلَةً وَاحِدَةً. فَجَاءَ جِبْرِيلُ عَلَيْهِ السَّلَامُ فَأَمَرَهُ أَنْ يَقْسِمَ أَصْحَابَهُ نِصْفَيْنِ: فَيُصَلِّي بِطَائِفَةٍ مِنْهُمْ، وَطَائِفَةٌ مُقْبِلُونَ عَلَى عَدُوِّهِمْ، قَدْ أَخَذُوا حِذْرَهُمْ وَأَسْلِحَتَهُمْ، فَيُصَلِّي بِهِمْ رَكْعَةً ثُمَّ يَتَأَخَّرُ هَؤُلَاءِ، وَيَتَقَدَّمُ أُولَئِكَ فَيُصَلِّي بِهِمْ رَكْعَةً، تَكُونُ لَهُمْ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَكْعَةً رَكْعَةً، وَلِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَكْعَتَانِ. (ن)', 'അബൂഹുറൈറ(റ): മുശ്രികുകളെ പ്രതിരോധിക്കാൻ നബി(സ) ളജ്നാൻ, ഉസ്ഫാൻ എന്നീ സ്ഥലങ്ങൾക്കിടയിൽ ഇറങ്ങി. ബഹുദൈവവിശ്വാസികൾ പറഞ്ഞു: തങ്ങളുടെ ആൺമക്കളെക്കാളും പെൺമക്കളെക്കാളും ഇഷ്ടമുള്ള ഒരു നിസ്കാരം ഇവർക്കുണ്ട്. അതിനാൽ ആ സമയം സംഘടിച്ച് നിങ്ങൾ അവർക്കു നേരെ അക്രമം അഴിച്ചു വിടുക. അപ്പോൾ ജിബ്രീൽ(അ) പ്രത്യക്ഷപ്പെട്ട് നബി(സ)യോട് അനുയായികളെ രണ്ടു സംഘമാക്കിത്തിരിക്കാനും, ഒരു വിഭാഗവുമായി നിസ്കരിക്കാനും, മറുവിഭാഗത്തെ ആയുധമെടുത്ത് ശക്തി സംഭരിച്ചവരായി ശത്രുക്കൾക്ക് അഭിമുഖീകരിച്ച് നിർത്താനും പറഞ്ഞു. അവരുമായി നബി(സ) ഒരു റക്അത്ത് നിസ്കരിക്കണം. പിന്നെ അവർ പിന്മാറി, മറ്റേ സംഘം മുന്നോട്ടു വരികയും, അവരുമായി നബി(സ) ഒരു റക്അത്ത് നിസ്കരിക്കുകയും വേണം. അങ്ങനെ ഓരോ വിഭാഗത്തിനും നബി(സ)യോടൊപ്പം ഒരു റക്അത്തും, നബി(സ)ക്ക് രണ്ട് റക്അത്തും ലഭിച്ചു. (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 686, 686, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=27 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنَّا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأُقِيمَتِ الصَّلَاةُ، فَقَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَامَتْ خَلْفَهُ طَائِفَةٌ وَطَائِفَةٌ مُوَاجِهَةَ الْعَدُوِّ، فَصَلَّى بِالَّذِينَ خَلْفَهُ رَكْعَةً وَسَجَدَ بِهِمْ سَجْدَتَيْنِ، ثُمَّ إِنَّهُمُ انْطَلَقُوا فَقَامُوا مَقَامَ أُولَئِكَ الَّذِينَ كَانُوا فِي وَجْهِ الْعَدُوِّ، وَجَاءَتْ تِلْكَ الطَّائِفَةُ فَصَلَّى بِهِمْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَكْعَةً وَسَجَدَ بِهِمْ سَجْدَتَيْنِ، ثُمَّ إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَلَّمَ فَسَلَّمَ الَّذِينَ خَلْفَهُ وَسَلَّمَ أُولَئِكَ. (ن)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): നബി(സ) ഞങ്ങളോടൊപ്പമായിരിക്കെ നിസ്കാരത്തിന്നായി ഇഖാമത്ത് വിളിച്ചു. നബി(സ)യും തിരുമേനി(സ)യുടെ പിന്നിൽ ഒരു സംഘവും നിസ്കാരത്തിനായി നിൽക്കുകയും, മറ്റൊരു സംഘം ശത്രുക്കളെ അഭിമുഖീകരിച്ചു നിൽക്കുകയും ചെയ്തു. നബി(സ) തൊട്ടു പിന്നിലുള്ള സംഘവുമായി രണ്ടു സുജൂദോടു കൂടി ഒരു റക്അത്ത് നിസ്കരിച്ചു. പിന്നെ അവർ പോയി ശത്രുക്കളെ അഭിമുഖീകരിച്ചു നിന്നിരുന്ന സംഘത്തിന്റെ സ്ഥാനത്ത് നിലയുറപ്പിക്കുകയും, അവിടെ നിന്ന സംഘം വരികയും നബി(സ) അവരോടൊപ്പം രണ്ടു സുജൂദോടു കൂടി ഒരു റക്അത്ത് നിസ്കരിക്കുകയും, തുടർന്ന് നബി(സ)യും നബി(സ)യുടെ പിന്നിലുള്ളവരും മറ്റേ സംഘവും സലാം വീട്ടുകയും ചെയ്തു. (ന)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 686, 686, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=27 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: فَرَضَ اللهُ الصَّلَاةَ عَلَى لِسَانِ نَبِيِّكُمْ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْحَضَرِ أَرْبَعًا، وَفِي السَّفَرِ رَكْعَتَيْنِ، وَفِي الْخَوْفِ رَكْعَةً. (د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നിങ്ങളുടെ നബി(സ)യുടെ നാവിലൂടെ അല്ലാഹു നിസ്കാരം നിർബന്ധമാക്കിയിരിക്കുന്നു. അത് നാട്ടിലാകുമ്പോൾ നാലു റക്അത്തും, യാത്രയിൽ രണ്ട് റക്അത്തും, യുദ്ധ വേളയിൽ (ഭയത്തിന്റെ സന്ദർഭത്തിൽ) ഒരു റക്അത്തുമാണ്. (മു,ദ,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ن']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 686, 687, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=27 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى بِذِي قَرَدٍ، وَصَفَّ النَّاسُ خَلْفَهُ صَفَّيْنِ، صَفًّا خَلْفَهُ، وَصَفًّا مُوَازِيَ الْعَدُوِّ، فَصَلَّى بِالَّذِينَ خَلْفَهُ رَكْعَةً، ثُمَّ انْصَرَفَ هَؤُلَاءِ إِلَى مَكَانِ هَؤُلَاءِ، وَجَاءَ أُولَئِكَ فَصَلَّى بِهِمْ رَكْعَةً، وَلَمْ يَقْضُوا. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ''ദീഖർദ്'' എന്ന സ്ഥലത്തു വെച്ച് നബി(സ) യുദ്ധവേളയിലെ നിസ്കാരം നിസ്കരിച്ചു. അപ്പോൾ ആളുകൾ രണ്ട് അണികളായി തിരിഞ്ഞ് ഒരു അണി നബി(സ)ക്കു പിന്നിലും, മറ്റേ അണി ശത്രുക്കളുടെ നേരെയുമായി നിന്നു. തൊട്ടുപിന്നിലുള്ളവരുമായി നബി(സ) ഒരു റക്അത്ത് നിസ്കരിച്ചു. തുടർന്ന് അവർ മറ്റേ അണി നിന്ന സ്ഥലത്ത് ചെല്ലുകയും, അവർ വരികയും, അവരോടൊപ്പം നബി(സ) ഒരു റക്അത്ത് കൂടി നിസ്കരിക്കുകയും ചെയ്തു. (ബാക്കിയുള്ളത്) അവർ നിസ്കരിച്ചില്ല. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 687, 687, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=27 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ ثَعْلَبَةَ بْنِ زَهْدَمٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ سَعِيدِ بْنِ الْعَاصِ بِطَبَرِسْتَانَ فَقَامَ فَقَالَ: أَيُّكُمْ صَلَّى مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الْخَوْفِ؟ فَقَالَ حُذَيْفَةُ: أَنَا، فَصَلَّى بِهَؤُلَاءِ رَكْعَةً وَبِهَؤُلَاءِ رَكْعَةً، وَلَمْ يَقْضُوا. (د,ن)', 'സഅ്ലബതുബ്നു സഹ്ദം(റ): ത്വബരിസ്ഥാനിൽ ഞങ്ങൾ സഈദുബ്നുൽ ആസി(റ)നോടൊപ്പം ഉണ്ടായിരുന്നു. അദ്ദേഹം ചോദിച്ചു: നിങ്ങളിൽ ആരാണ് നബി(സ)യോടൊപ്പം യുദ്ധവേളയിലെ നിസ്കാരം നിർവ്വഹിച്ചത്? ഹുദൈഫ(റ) പറഞ്ഞു: ഞാൻ നിർവ്വഹിച്ചിട്ടുണ്ട്. അവിടുന്ന് ഒരു വിഭാഗവുമായി ഒരു റക്അത്ത് നിസ്കരിച്ചു, മറ്റേ വിഭാഗത്തോടൊപ്പവും ഒരു റക്അത്താണ് നിർവ്വഹിച്ചത്. അവർ (ബാക്കിയുള്ളത്) നിർവ്വഹിച്ചില്ല. (ദ,ന)', 'ثَعْلَبَةَ بْنِ زَهْدَمٍ', 'സഅ്ലബതുബ്നു സഹ്ദം(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 687, 687, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=27 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَنَا لَمَّا رَجَعَ مِنَ الْأَحْزَابِ: "لَا يُصَلِّيَنَّ أَحَدٌ الْعَصْرَ إِلَّا فِي بَنِي قُرَيْظَةَ". فَأَدْرَكَ بَعْضَهُمُ الْعَصْرُ فِي الطَّرِيقِ، فَقَالَ بَعْضُهُمْ: لَا نُصَلِّي حَتَّى نَأْتِيَهَا، وَقَالَ بَعْضُهُمْ: بَلْ نُصَلِّي، لَمْ يُرَدْ مِنَّا ذَلِكَ، فَذُكِرَ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَلَمْ يُعَنِّفْ وَاحِدًا مِنْهُمْ. (خ)', 'ഇബ്നുഉമർ(റ): ''അഹ്സാബിൽ'' നിന്ന് മടങ്ങവെ നബി(സ) ഞങ്ങളോട് പറഞ്ഞു: "ബനൂഖുറൈദയിൽ ചെന്നിട്ടല്ലാതെ ആരും അസ്ർ നിസ്കരിക്കരുത്" വഴിയിൽ വെച്ചുതന്നെ അസ്റിനു സമയമായി. അപ്പോൾ ചിലർ പറഞ്ഞു: ഞങ്ങൾ അവിടെ (ബനൂഖുറൈദയിൽ) ചെന്നിട്ടല്ലാതെ അസർ നിസ്കിക്കുകയില്ല. മറ്റു ചിലർ പറഞ്ഞു: ഇല്ല, ഞങ്ങൾ ഇവിടെ വെച്ച് നിസ്കരിക്കും. നബി(സ) അതല്ല നമ്മിൽനിന്ന് ഉദ്ദേശിച്ചത്. ഈ വിവരം നബി(സ)യോട് പറഞ്ഞപ്പോൾ നബി(സ) ആരെയും കുറ്റപ്പെടുത്തിയില്ല. (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 687, 687, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=27 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ مَرْوَانَ بْنِ الْحَكَمِ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ سَأَلَ أَبَا هُرَيْرَةَ: هَلْ صَلَّيْتَ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الْخَوْفِ؟ فَقَالَ أَبُو هُرَيْرَةَ: نَعَمْ، قَالَ: مَتَى؟ قَالَ: عَامَ غَزْوَةِ نَجْدٍ، قَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِصَلَاةِ الْعَصْرِ، وَقَامَتْ مَعَهُ طَائِفَةٌ، وَطَائِفَةٌ أُخْرَى مُقَابِلَ الْعَدُوِّ وَظُهُورُهُمْ إِلَى الْقِبْلَةِ، فَكَبَّرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَكَبَّرُوا جَمِيعًا: الَّذِينَ مَعَهُ وَالَّذِينَ يُقَابِلُونَ الْعَدُوَّ، ثُمَّ رَكَعَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَكْعَةً وَاحِدَةً، وَرَكَعَتْ مَعَهُ الطَّائِفَةُ الَّتِي تَلِيهِ، ثُمَّ سَجَدَ وَسَجَدَتِ الطَّائِفَةُ الَّتِي تَلِيهِ، وَالْآخَرُونَ قِيَامٌ مُقَابِلَ الْعَدُوِّ، ثُمَّ قَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَامَتِ الطَّائِفَةُ الَّتِي مَعَهُ، فَذَهَبُوا إِلَى الْعَدُوِّ فَقَابَلُوهُمْ، وَأَقْبَلَتِ الطَّائِفَةُ الَّتِي كَانَتْ مُقَابِلَ الْعَدُوِّ فَرَكَعُوا وَسَجَدُوا، وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَائِمٌ كَمَا هُوَ، ثُمَّ قَامُوا فَرَكَعَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَكْعَةً أُخْرَى، وَرَكَعُوا مَعَهُ، وَسَجَدَ وَسَجَدُوا مَعَهُ. ثُمَّ أَقْبَلَتِ الطَّائِفَةُ الَّتِي كَانَتْ مُقَابِلَ الْعَدُوِّ فَرَكَعُوا وَسَجَدُوا، وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَاعِدٌ وَمَنْ مَعَهُ، ثُمَّ كَانَ السَّلَامُ فَسَلَّمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَسَلَّمُوا جَمِيعًا، فَكَانَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَكْعَتَانِ وَلِكُلِّ رَجُلٍ مِنَ الطَّائِفَتَيْنِ رَكْعَتَانِ رَكْعَتَانِ. (د,ن)', 'മർവ്വാനുബ്നുൽ ഹകം(റ): അദ്ദേഹം അബൂഹുറൈറ(റ)യോട് ചോദിച്ചു: താങ്കൾ നബി(സ)യോടൊപ്പം സ്വലാത്തുൽ ഖൗഫ് നിർവ്വഹിച്ചിട്ടുണ്ടോ? അബൂഹുറൈറ(റ) പറഞ്ഞു: അതെ. അദ്ദേഹം ചോദിച്ചു: എപ്പോൾ? അബൂഹുറൈറ(റ) പറഞ്ഞു: നജ്ദ് യുദ്ധം നടന്ന വർഷമാണത്, നബി(സ) അസ്ർ നിസ്കാരത്തിനായി നിന്നു, നബി(സ)യോടൊപ്പം ഒരു സംഘവും. മറ്റൊരു സംഘം ശത്രുക്കളുടെ നേരെയും. അവരുടെ പിൻഭാഗം ഖിബ്ലക്കു നേരെയായിരുന്നു. നബി(സ) തക്ബീർ ചൊല്ലിയപ്പോൾ അവരെല്ലാവരും തക്ബീർ ചൊല്ലി. അഥവാ നബിയോടൊപ്പമുള്ളവരും ശത്രുക്കളുടെനേരെ നിൽക്കുന്നവരും. പിന്നീട് നബി(സ)യും നബി(സ)യോടടുത്തുള്ളവരും ഒരു റുകൂഉം രണ്ട് സുജൂദും (ഒരു റക്അത്ത്) ചെയ്യുകയും, മറ്റുള്ളവർ ശത്രുക്കൾക്കെതിരെ നിലകൊള്ളുകയും ചെയ്തു. പിന്നീട് നബി(സ)യും ഒപ്പമുള്ള സംഘവും എഴുന്നേറ്റു. ശേഷം അവർ ശത്രുക്കളെ അഭിമുഖീകരിക്കാനായി ചെല്ലുകയും, അവിടെ നിൽക്കുകയും ചെയ്തു. ശത്രുക്കളെ അഭിമുഖീകരിച്ചു നിന്ന സംഘം റുകൂഉം സുജൂദും ചെയ്തു. നബി(സ) നിന്ന നിൽപിൽ തന്നെ നിൽക്കുകയായിരുന്നു. പിന്നെയവർ നിൽക്കുകയും നബി(സ) ഒരു റക്അത്തു കൂടി നിസ്കരിക്കുകയും ചെയ്തു. അവരും നബി(സ)യോടൊപ്പം റുകൂഉം സുജൂദും ചെയ്തു. പിന്നീട് ശത്രുക്കളെ അഭിമുഖീകരിച്ചു നിന്ന സംഘം മുന്നോട്ടു വരികയും, റുകൂഉം സുജൂദും ചെയ്യുകയും ചെയ്തു. നബി(സ)യും ഒപ്പമുള്ളവരും ഇരിക്കുകയായിരുന്നു. പിന്നീട് നബി(സ)യും രണ്ട് സംഘത്തിലെ ആളുകളും സലാം വീട്ടി. നബി(സ)ക്ക് രണ്ട് റക്അത്തും സംഘത്തിലുണ്ടായിരുന്നവർക്ക് രണ്ട് റക്അത്ത് വീതവും ലഭിച്ചു. (ദ,ന)', 'مَرْوَانَ بْنِ الْحَكَمِ', 'മർവ്വാനുബ്നുൽ ഹകം(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 687, 688, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=27 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: صَلَّى بِنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الْخَوْفِ، فَقَامُوا صَفًّا خَلْفَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَصَفٌّ مُسْتَقْبِلَ الْعَدُوِّ، فَصَلَّى بِهِمْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَكْعَةً، ثُمَّ جَاءَ الْآخَرُونَ فَقَامُوا مَقَامَهُمْ، وَاسْتَقْبَلَ هَؤُلَاءِ الْعَدُوَّ، فَصَلَّى بِهِمُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَكْعَةً، ثُمَّ سَلَّمَ، فَقَامَ هَؤُلَاءِ فَصَلَّوْا لِأَنْفُسِهِمْ رَكْعَةً ثُمَّ سَلَّمُوا ثُمَّ ذَهَبُوا، فَقَامُوا مَقَامَ أُولَئِكَ مُسْتَقْبِلِي الْعَدُوِّ، وَرَجَعَ أُولَئِكَ إِلَى مَقَامِهِمْ، فَصَلَّوْا لِأَنْفُسِهِمْ رَكْعَةً، ثُمَّ سَلَّمُوا. وَفِي رِوَايَةٍ: فَكَبَّرَ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَكَبَّرَ الصَّفَّانِ جَمِيعًا. (د)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): യുദ്ധ വേളയിലെ നിസ്കാരം നബി(സ) ഞങ്ങളോടൊത്ത് ഒരു പ്രാവശ്യം നിസ്കരിച്ചു. ഒരു അണി നബി(സ)യുടെ പിന്നിലും മറ്റൊരു അണി ശത്രുക്കളുടെ നേരെയുമായിരുന്നു. അവരുമായി നബി(സ) ഒരു റക്അത്ത് നിസ്കരിച്ചു. പിന്നീട് മറ്റേ അണി ഇവരുടെ സ്ഥാനത്ത് വന്നു നിന്നു. മറ്റേ അണി ശത്രുക്കൾക്കു നേരെയും നിന്നു. അവരുമായി നബി(സ) ഒരു റക്അത്ത് നിസ്കരിച്ച് സലാം വീട്ടി. ശേഷം അവർ എഴുന്നേറ്റ് സ്വന്തമായി ഒരു റക്അത് നമസ്കരിക്കുകയും സലാം വീട്ടിയ ശേഷം ശത്രുക്കളെ അഭിമുഖീകരിച്ചിരിക്കുന്നവരുടെ സ്ഥാനത്ത് ചെന്ന് നിൽക്കുകയും ചെയ്തു. മറ്റേ വിഭാഗം മടങ്ങി അവരുടെ ഭാഗത്തായി ഒരു റക്അത്ത് നിസ്കരിക്കുകയും സലാം വീട്ടുകയും ചെയ്തു. മറ്റൊരു റിപ്പോർട്ടിൽ: നബി(സ) തക്ബീർ ചൊല്ലി, രണ്ടു സംഘവും ഒരുമിച്ച് തക്ബീർ ചൊല്ലി. (ബു,ദ,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 688, 688, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=27 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=27 and h.hadith_no=14), 1, 'وَفِي رِوَايَةٍ: فَكَبَّرَ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَكَبَّرَ الصَّفَّانِ جَمِيعًا. (د)', 'മറ്റൊരു നിവേദനിൽ: നബി(സ) തക്ബീർ ചൊല്ലി, രണ്ടു സംഘവും ഒരുമിച്ച് തക്ബീർ ചൊല്ലി. (ബു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي خَوْفِ الظُّهْرِ، فَصَفَّ بَعْضُهُمْ خَلْفَهُ وَبَعْضُهُمْ بِإِزَاءِ الْعَدُوِّ، فَصَلَّى بِهِمْ رَكْعَتَيْنِ ثُمَّ سَلَّمَ. فَانْطَلَقَ الَّذِينَ صَلَّوْا مَعَهُ فَوَقَفُوا مَوْقِفَ أَصْحَابِهِمْ، ثُمَّ جَاءَ أُولَئِكَ فَصَلَّوْا خَلْفَهُ، فَصَلَّى بِهِمْ رَكْعَتَيْنِ ثُمَّ سَلَّمَ. فَكَانَتْ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَرْبَعًا، وَلِأَصْحَابِهِ رَكْعَتَيْنِ رَكْعَتَيْنِ. (د,ن)', 'അബൂബക്റ(റ): യുദ്ധവേളയിൽ നബി(സ) ളുഹ്ർ നിസ്കരിച്ചു. ചിലർ നബി(സ)ക്കു പിന്നിലും മറ്റു ചിലർ ശത്രുക്കൾക്കു നേരെയുമായിക്കൊണ്ട് അണി നിരന്നു. അവരുമായി രണ്ട് റക്അത്ത് നിസ്കരിച്ച് നബി(സ) സലാം വീട്ടി. ശേഷം നബി(സ)യോടൊപ്പം നിസ്കരിച്ചവർ മറ്റെ വിഭാഗം നിന്ന സ്ഥലത്തു പോയി നിന്നു. പിന്നീട് മറ്റേ സംഘം വരികയും നബി(സ)ക്കു പിന്നിലായി നിസ്കരിക്കുകയും ചെയ്തു. അവരോടൊപ്പം നബി(സ) രണ്ട് റക്അത്ത് നിസ്കരിച്ച് സലാം വീട്ടി. അങ്ങനെ നബി(സ)ക്ക് നാല് റക്അത്തും, അനുചരന്മാർക്ക് രണ്ട് റക്അത്ത് വീതവും കിട്ടി. (ദ,ന)', 'أَبِي بَكْرَةَ', 'അബൂബക്റ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 688, 689, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=27 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ عَبْدِ اللهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَامَ النَّاسُ مَعَهُ، فَكَبَّرَ وَكَبَّرُوا، ثُمَّ رَكَعَ وَرَكَعَ أُنَاسٌ مِنْهُمْ، ثُمَّ سَجَدَ وَسَجَدُوا، ثُمَّ قَامَ إِلَى الرَّكْعَةِ الثَّانِيَةِ، فَتَأَخَّرَ الَّذِينَ سَجَدُوا مَعَهُ وَحَرَسُوا إِخْوَانَهُمْ، وَأَتَتِ الطَّائِفَةُ الْأُخْرَى فَرَكَعُوا مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَسَجَدُوا، وَالنَّاسُ كُلُّهُمْ فِي صَلَاةٍ يُكَبِّرُونَ، وَلَكِنْ يَحْرُسُ بَعْضُهُمْ بَعْضًا. (ن)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): നിസ്കാരത്തിന്നായി നബി(സ)യും കൂടെ ജനങ്ങളും നിന്നു. നബി(സ)യും അവരും തക്ബീർ ചൊല്ലി, നബി(സ)യും അവരിൽ കുറച്ചാളുകളും റുകൂഅ് ചെയ്തു. പിന്നെ നബി(സ)യും അവരും സുജൂദ് ചെയ്തു. തുടർന്ന് രണ്ടാമത്തെ റക്അത്തിനായി എഴുന്നേറ്റു. നബി(സ)യോടൊപ്പം സുജൂദ് ചെയ്തവർ പിന്നോട്ടുമാറി അവരുടെ സഹോദരങ്ങളെ സംരക്ഷിച്ചു കൊണ്ട് നിന്നു. മറ്റേ വിഭാഗം മുന്നോട്ടുവന്ന് നബി(സ)യോടൊപ്പം റുകൂഉം സുജൂദും ചെയ്തു. ജനങ്ങളെല്ലാം തക്ബീർ ചൊല്ലി നിസ്കരിക്കുകയായിരുന്നു, എങ്കിലും അവർ പരസ്പരം കാവൽ നിൽക്കുന്നുമുണ്ടായിരുന്നു. (ന)', 'عَبْدِ اللهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 689, 689, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=27 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَا كَانَتْ صَلَاةُ الْخَوْفِ إِلَّا سَجْدَتَيْنِ كَصَلَاةِ أَحْرَاسِكُمْ هَؤُلَاءِ الْيَوْمَ خَلْفَ أَئِمَّتِكُمْ هَؤُلَاءِ، إِلَّا أَنَّهَا كَانَتْ عُقَبًا، قَامَتْ طَائِفَةٌ مِنْهُمْ وَهُمْ جَمِيعًا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَسَجَدَتْ مَعَهُ طَائِفَةٌ مِنْهُمْ، ثُمَّ قَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَامُوا مَعَهُ جَمِيعًا، ثُمَّ رَكَعَ وَرَكَعُوا مَعَهُ جَمِيعًا، ثُمَّ سَجَدَ فَسَجَدَ مَعَهُ الَّذِينَ كَانُوا قِيَامًا أَوَّلَ مَرَّةٍ، فَلَمَّا جَلَسَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَالَّذِينَ سَجَدُوا مَعَهُ فِي آخِرِ صَلَاتِهِمْ سَجَدَ الَّذِينَ كَانُوا قِيَامًا لِأَنْفُسِهِمْ، ثُمَّ جَلَسُوا، فَجَمَعَهُمْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالتَّسْلِيمِ. (ن)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): സ്വലാതുൽ ഖൗഫ് രണ്ട് റക്അത്ത് മാത്രമായിരുന്നു. അതായത് ഇന്നത്തെ നിങ്ങളുടെ കാവൽക്കാർ നിങ്ങളുടെ ഈ നേതാക്കളുടെ പിന്നിൽ നിസ്കരിക്കും പോലെ. പക്ഷെ, അത് ഒരു സംഘം നിസ്കരിച്ച ശേഷം മറ്റേ സംഘം നിസ്കരിക്കുക എന്ന ശൈലിയായിരുന്നു. അവരിൽ ഒരു വിഭാഗം നബി(സ)യോടൊപ്പം നിൽക്കുന്നു, ഒരു വിഭാഗം നബി(സ)യോടൊപ്പം സുജൂദ് ചെയ്യുന്നു. പിന്നെ നബി(സ)യും അവരും എഴുന്നേൽക്കുന്നു. പിന്നെ നബി(സ)യും അവരും റുകൂഅ് ചെയ്യുന്നു. പിന്നീട് നബി(സ)യും ആദ്യം നിന്നവരും സുജൂദ് ചെയ്യുന്നു. നബി(സ)യും അവിടത്തോടൊപ്പം സുജൂദ് ചെയ്തവരും അവരുടെ നിസ്കാരത്തിന്റെ അവസാനം ഇരുന്നപ്പോൾ നേരത്തെ നിന്നിരുന്നവർ തനിച്ച് സുജൂദ് ചെയ്യുകയും ഇരിക്കുകയും ചെയ്തു. അങ്ങനെ എല്ലാവരോടുമൊപ്പം നബി(സ) സലാം വീട്ടി. (ന)', 'ابْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 689, 689, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=27 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ سَهْلِ بْنِ أَبِي حَثْمَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى بِهِمْ صَلَاةَ الْخَوْفِ، فَصَفَّ صَفًّا خَلْفَهُ وَصَفًّا مُصَافُّو الْعَدُوِّ، فَصَلَّى بِهِمْ رَكْعَةً، ثُمَّ ذَهَبَ هَؤُلَاءِ وَجَاءَ أُولَئِكَ فَصَلَّى بِهِمْ رَكْعَةً، ثُمَّ قَامُوا فَقَضَوْا رَكْعَةً رَكْعَةً. (ن)', 'സഹ്ലുബ്നു അബീഹഥ്മ(റ): നബി(സ) അവരുമായി സ്വലാതുൽ ഖൗഫ് നിർവ്വഹിച്ചു. ഒരു സംഘത്തെ നബി(സ)യുടെ പിന്നിലും, മറ്റൊരു സംഘത്തെ ശത്രുവിനു നേരെയും നിർത്തി. ആദ്യത്തെ സംഘവുമായി നബി(സ) ഒരു റക്അത്ത് നിസ്കരിച്ചു. പിന്നീട് അവർ പോയി മറ്റേ സംഘം വന്നു. അവർ നബി(സ)യോടൊപ്പം ഒരു റക്അത്ത് നിസ്കരിച്ചു. പിന്നീട് അവർ ഓരോ റക്അത്ത് കൂടി നിസ്കരിച്ച് നിസ്കാരം പൂർത്തിയാക്കി. (ന)', 'سَهْلِ بْنِ أَبِي حَثْمَةَ', 'സഹ്ലുബ്നു അബീഹഥ്മ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 690, 690, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=27 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا خَافَ قَوْمًا قَالَ: "اللَّهُمَّ إِنَّا نَجْعَلُكَ فِي نُحُورِهِمْ، وَنَعُوذُ بِكَ مِنْ شُرُورِهِمْ". (د)', 'അബൂമൂസൽ അശ്അരി(റ): ഒരു സമൂഹത്തെ ഭയന്നാൽ നബി(സ) ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ! ഞങ്ങൾ നിന്നെ അവർക്കെതിരിൽ പരിചയാക്കുന്നു. അവരിൽ നിന്നുള്ള തിന്മയിൽ നിന്ന് നിന്നോട് ഞങ്ങൾ രക്ഷ തേടുന്നു." (ദ)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമൂസൽ അശ്അരി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 690, 690, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=27 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنِ ابْنِ عَبْدِ اللهِ بْنِ أُنَيْسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: بَعَثَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى خَالِدِ بْنِ سُفْيَانَ الْهُذَلِيِّ، وَكَانَ نَحْوَ عُرَنَةَ وَعَرَفَاتٍ، فَقَالَ: "اذْهَبْ فَاقْتُلْهُ". قَالَ: فَرَأَيْتُهُ وَحَضَرَتْ صَلَاةُ الْعَصْرِ، فَقُلْتُ: إِنِّي أَخَافُ أَنْ يَكُونَ بَيْنِي وَبَيْنَهُ مَا إِنْ أُؤَخِّرِ الصَّلَاةَ. فَانْطَلَقْتُ أَمْشِي - وَأَنَا أُصَلِّي أُومِئُ إِيمَاءً - نَحْوَهُ، فَلَمَّا دَنَوْتُ مِنْهُ قَالَ لِي: مَنْ أَنْتَ؟ قُلْتُ: رَجُلٌ مِنَ الْعَرَبِ، بَلَغَنِي أَنَّكَ تَجْمَعُ لِهَذَا الرَّجُلِ، فَجِئْتُكَ فِي ذَاكَ، قَالَ: إِنِّي لَفِي ذَاكَ، فَمَشَيْتُ مَعَهُ سَاعَةً، حَتَّى إِذَا أَمْكَنَنِي عَلَوْتُهُ بِسَيْفِي حَتَّى بَرَدَ. (د)', 'ഇബ്നുഅബ്ദില്ലാഹിബ്നു ഉനൈസ്(റ): ഖാലിദുബ്നു സുഫ്യാൻ ഹുദൈലിയുടെ അടുത്തേക്ക് നബി(സ) എന്നെ നിയോഗിച്ചു. അയാൾ ഉർന, അറഫാത്ത് എന്നീ ഭാഗങ്ങളിലായിരുന്നു. തിരുമേനി(സ) പറഞ്ഞു: "പോകൂ, അയാളെ വധിക്കൂ." ഇബ്നുഅബ്ദില്ലാഹിബ്നു ഉനൈസ്(റ) പറഞ്ഞു: അസ്ർ നിസ്കാര സമയമായപ്പോൾ ഞാനയാളെ കണ്ടു. ഞാൻ സ്വയം പറഞ്ഞു: നിസ്കാരം പിന്തിച്ചാൽ എന്റെ ലക്ഷ്യപ്രാപ്തിക്ക് തടസ്സം നേരിടുമോ എന്ന് ഞാൻ ഭയപ്പെട്ടു. അതിനാൽ ഞാൻ അയാളുടെ നേരെ നടന്നുനീങ്ങി - അതോടൊപ്പം ഞാൻ ആംഗ്യം കാണിച്ചുകൊണ്ട് നിസ്കരിക്കുന്നുമുണ്ടായിരുന്നു - അയാളെ സമീപിച്ചപ്പോൾ അയാൾ എന്നോട് ചോദിച്ചു: നിങ്ങൾ ആരാണ്? ഞാൻ പറഞ്ഞു: ഒരു അറബിയാണ്, ഈ ആൾക്ക് (നബി(സ)ക്ക്) എതിരായി നിങ്ങൾ ആളുകളെ സംഘടിപ്പിക്കുന്നതായി ഞാൻ അറിഞ്ഞു. ആ വിഷയകമായിട്ടാണ് ഞാൻ നിങ്ങളെ സമീപിച്ചത്. അയാൾ പറഞ്ഞു: അതെ, ഞാൻ ആ സംഗതിയിൽ തന്നെയാണ്. കുറച്ചുസമയം അയാളുമായി ഞാൻ നടന്നു. അങ്ങനെ അനുകൂല സന്ദർഭം കിട്ടിയപ്പോൾ ഞാൻ വാളുയർത്തി അയാളെ വധിച്ചു. (ദ)', 'ابْنِ عَبْدِ اللهِ بْنِ أُنَيْسٍ', 'ഇബ്നുഅബ്ദില്ലാഹിബ്നു ഉനൈസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 690, 690, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=27 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
